from __future__ import annotations
from abc_creative_gold_v5_101_200_support import make_spec, register_craft
FACTS={
"Armchair":"Upholstered single-seat chair with arms; stable floor placement keeps it from becoming climbing equipment.","Blanket":"Flexible textile layer provides warmth/comfort; loose bedding should suit age and sleep-safety context.","Chair":"Raised seat supports sitting; standing or rocking on ordinary chairs increases fall risk.","Dresser":"Storage furniture with drawers; tall units can tip and should be anchored where appropriate.","Envelope":"Folded paper container carries letters/small flat items; it belongs to storage/mail, not furniture.","Fan":"Device moves air with rotating blades or blower; guards and electrical safety matter, fingers stay away.","Garage":"Vehicle/storage/work room; moving cars, tools, chemicals, and doors make it adult-managed space.","Hanger":"Clothing support hangs garments from a rail/hook; wire/plastic shapes are not toys.","Iron":"Heated appliance presses fabric; hot soleplate, steam, and cord make it adult-only.","Jug":"Handled container pours liquid; material and contents determine weight, breakage, or heat hazards.","Kettle":"Appliance/vessel heats water; boiling water, steam, and hot surfaces are adult-only.","Lamp":"Light fixture converts electrical energy to light; bulbs/shades can heat and cords/outlets need safe placement.","Mattress":"Large padded sleep support used on a compatible bed/base; firmness and sleep guidance vary by age.","Nightlight":"Low-level light helps orientation at night; electrical units still need safe outlet/cord placement.","Oven":"High-heat cooking appliance; door, racks, cookware, and steam remain adult-only.","Pillow":"Soft head/body support; sleep-safety recommendations vary with age, especially for infants.","Quilted Cushion":"Padded fabric cushion stitched through layers; it is seating/decor support, not safe climbing equipment.","Rug":"Textile floor covering adds comfort or defines an area; non-slip backing/flat edges reduce trips.","Soap":"Cleaning substance lifts oils/dirt with water; avoid eyes/mouth and use the right product for hands, dishes, or surfaces.","Towel":"Absorbent textile dries skin or surfaces; wet towels should be hung/spread to dry rather than left on floors.","Utensil Drawer":"Kitchen drawer stores eating/prep tools; sharp utensils must be secured away from children.","Vase":"Container displays flowers; glass/ceramic versions can break and should sit on stable surfaces.","Window":"Opening admits light/air/view; screens are not fall protection and children stay away from unsafe open heights.","Xylophone":"Tuned-bar musical instrument; deliberate home-object comparison item, not furniture.","Yellow Cushion":"Cushion with yellow cover; color changes appearance, not its support function.","Zen Garden":"Small arranged sand/stone garden used for visual/tactile contemplation; tiny stones may be choking hazards for young children.","Alarm Clock":"Timepiece with alarm function signals a set time; it does not know whether a person has slept enough.","Bed":"Furniture supports sleep/rest; safe setup depends on age, frame, mattress, rails, and surrounding space.","End Table":"Small table beside seating/bed holds lightweight items; heavy/hot objects need stable adult placement.","Frame":"Border/support presents or protects a picture; glass-front frames can break.","Glass":"Drinking vessel or transparent material depending context; breakable glassware needs careful adult judgment around children.","Indoor Plant":"Plant grown indoors needs species-appropriate light/water; some houseplants are toxic to children/pets if eaten.","Jar":"Rigid lidded container stores foods/items; glass can break and sealed contents may need adult access.","Key":"Cut or coded object operates a lock; small keys can be choking hazards and access keys should stay with responsible users.","Laundry Basket":"Container gathers/carries laundry; it is not a ride-on toy and loads can block visibility.","Mirror":"Reflective surface forms an image; securely mounted/nonbreakable designs reduce injury risk.","Ottoman":"Low upholstered footrest/seat; storage ottomans may have lids/hinges needing finger safety.","Picture":"Image/photo/artwork represents a scene or subject; it is a visual item rather than a functional appliance.","Refrigerator":"Insulated appliance keeps food cold; doors, shelves, and food storage have safety rules and it is never a hiding place.","Umbrella":"Portable canopy protects from rain/sun; pointed tips and opening mechanism need space.","Vacuum":"Powered appliance removes dust/debris by airflow; cords, moving brush, and electricity require supervised use.","X-shaped Shelf":"Shelf/support arranged in an X-like form; wall anchoring/load limits still matter.","Cupboard":"Enclosed storage furniture with shelves/doors; contents determine whether child locks or high storage are needed.","Door":"Movable barrier opens/closes a passage; hinges and closing edges are pinch points.","Hallway":"Passage connects rooms; keeping it clear supports safe movement and emergency exit.","Napkin":"Cloth/paper wipes hands/mouth during meals; it is not a substitute for washing when cleaning is needed.","Quilt":"Layered stitched bedcover/textile; warmth and sleep suitability depend on age/context.","Table":"Flat raised work/eating surface; stable use means no climbing or edge-loading.","Wardrobe":"Tall clothing-storage cabinet; anchoring and door/drawer safety can prevent tip/pinch hazards.","Yarn":"Long fiber strand for craft/textiles; loose lengths can tangle and need supervision.","Zipper":"Interlocking teeth/slider closes fabric openings; fingers/fabric can catch if pulled carelessly.","Sofa":"Upholstered multi-seat furniture for sitting/resting; arms/back are not climbing platforms.",}
ACTIONS={"Iron":"Point only; hot appliance stays with an adult.","Kettle":"Point only; no pouring/steam mime.","Oven":"Point only; adult heat zone.","Fan":"Point; trace guarded airflow, keep fingers still.","Window":"Point; show a stay-back-from-open-height palm.","Garage":"Point; say vehicle/tool area is adult-managed.","Utensil Drawer":"Point; say sharp items stay secured.","Glass":"Point; say breakable item—handle only when suitable.","Vase":"Point; keep hands away from breakable real vase.","Vacuum":"Point; adult/supervised powered appliance.","Yarn":"Trace one loose curve in air; no wrapping.","Zen Garden":"Point; tiny stones stay out of mouths."}
